  $new = (@($dir) + $parts) -join ';'
  [Environment]::SetEnvironmentVariable('Path', $new, 'User')
  echo "Added to User PATH."
}
echo "--- verify (User PATH, Git/sh entries) ---"
[Environment]::GetEnvironmentVariable('Path','User') -split ';' | Where-Object { $_ -match 'Git|\.local' }

$t="C:\Users\DELL\AppData\Local\Temp\opencode\shlink"; New-Item -ItemType Directory -Force -Path $t | Out-Null; Remove-Item "$t\*" -Force -ErrorAction SilentlyContinue
try { New-Item -ItemType SymbolicLink -Path "$t\sh.exe" -Target "C:\Program Files\Git\usr\bin\sh.exe" -ErrorAction Stop | Out-Null; echo "SYMLINK_CREATED" } catch { echo "SYMLINK_FAILED: $($_.Exception.Message)" }
